from pathlib import Path
from html import escape
import json, os, subprocess, xml.etree.ElementTree as ET
base=Path(__file__).resolve().parents[1]; out=base/'docs/POC_SIMPLE_GUIDE.html'
revision=os.environ.get('POC_EVIDENCE_REVISION') or subprocess.check_output(['git','rev-parse','HEAD'],cwd=base,text=True).strip()
ref=os.environ.get('GITHUB_HEAD_REF') or subprocess.check_output(['git','branch','--show-current'],cwd=base,text=True).strip()
run_id=os.environ.get('GITHUB_RUN_ID','37267381702')
tests=sum(int(ET.parse(p).getroot().get('tests','0')) for p in base.glob('*/target/surefire-reports/TEST-*.xml'))
support_path=base/'artifacts/support-results.json'
support=json.loads(support_path.read_text()) if support_path.exists() else []
support_ok=bool(support) and all(x.get('status')=='PASS' for x in support)
repo='https://github.com/srinu7893/otel-payment-platform-poc/blob/'+ref+'/'
def source(path,label):return f'<a href="{repo+path}">{escape(label)}</a>'
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+escape(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def code(s):return '<pre><code>'+escape(s)+'</code></pre>'
sections=[]
def add(id,title,body):sections.append((id,title,body))
add('idea','1. Start here: what problem are we solving?', '''<p>A customer says: <strong>“My payment is slow, and I did not receive a notification.”</strong> Several services took part. We need to find the affected payment, identify the slow or broken step, understand how many customers are affected, and check whether our fix worked.</p><div class="cards"><div><b>Logs = what happened</b><p>Payment completed, bank timed out, publishing failed. Search the actual event text and IDs.</p></div><div><b>Trace = one journey</b><p>A timeline of one request across services. Find the operation that was slow or failed.</p></div><div><b>Metrics = how much</b><p>Requests, errors, latency, memory and queue depth over time. See the size of the problem.</p></div></div><p><strong>OpenTelemetry (OTel)</strong> is the common way we instrument services and move this evidence to observability systems. <strong>Observability</strong> means using that evidence to understand what the system is doing. OTel does not automatically repair a payment or prove a root cause.</p><p class="callout">The useful path is: see a symptom → find its events → open its trace → check the wider impact → take a safe action → prove recovery.</p>''')
add('services','2. Our services, in everyday language',table(['Part','What it does'],[
('Frontend','The customer and support screens. It calls our API. Browser tests exist; browser OTel instrumentation is a future addition.'),('API Gateway','The front door. Checks customer JWT/roles, routes requests and exposes support health information.'),('Auth','Checks demo login details and issues the customer access token.'),('Customer','Checks the customer profile and linked account.'),('Payment','Owns payments, transfers, refunds, risk checks and reconciliation. Saves the payment and notification work.'),('Gateway adapter','Calls the bank. Handles timeouts and circuit-breaker behavior. Different from the API Gateway.'),('Mock Bank','A fake bank ledger and failure laboratory. No real money is moved.'),('Notification','Receives queued events, avoids duplicate delivery, retries and records simulated delivery.'),('PostgreSQL + RabbitMQ','PostgreSQL stores business state. RabbitMQ carries asynchronous notification events. They are business infrastructure, not OTel storage.')])+'''<h3>Follow one successful payment</h3><ol><li>The customer signs in through API Gateway → Auth.</li><li>The payment request enters API Gateway → Payment. Payment checks account ownership with Customer.</li><li>Payment calls Gateway adapter → Mock Bank. The bank performs the simulated operation.</li><li>Payment saves its result and an <strong>outbox event</strong> in one database transaction. The outbox is saved work waiting to be published.</li><li>A later worker publishes that event to RabbitMQ. Notification consumes it and saves a deduplicated simulated delivery.</li></ol><p>Notification can finish after the HTTP response. A successful HTTP response and a delivered notification are two different checks.</p>''')
add('integration','3. What did we actually add for OTel?', '''<p>We attach the <strong>OTel Java agent</strong> when each of the seven Java services starts. It observes supported framework operations such as HTTP requests, JDBC database calls and RabbitMQ messaging. We also added application-specific outbox tracing and publishing metrics.</p>'''+code('JAVA_TOOL_OPTIONS=-javaagent:/otel/opentelemetry-javaagent.jar\nOTEL_SERVICE_NAME=payment-service\nOTEL_EXPORTER_OTLP_ENDPOINT=http://otel-collector:4318\nOTEL_EXPORTER_OTLP_PROTOCOL=http/protobuf\nOTEL_TRACES_EXPORTER=otlp\nOTEL_METRICS_EXPORTER=otlp\nOTEL_LOGS_EXPORTER=otlp\nOTEL_PROPAGATORS=tracecontext,baggage')+'''<p>In plain language: <code>JAVA_TOOL_OPTIONS</code> loads the agent; <code>OTEL_SERVICE_NAME</code> identifies the service; the endpoint tells it where to send evidence; the exporter settings enable all three signals; the propagators carry context between calls. These values are configured in '''+source('docker-compose.otel.yml','the OTel Compose overlay')+'''.</p>'''+table(['Evidence','Where it comes from'],[('Logs','Our application still writes the business messages through SLF4J/Logback. The agent attaches service and active trace/span context and sends them over OTLP. It does not invent the messages or tail Docker files.'),('Traces','The agent times supported server/client/database/message operations. A <strong>span</strong> is one operation; related spans form a <strong>trace</strong>.'),('Metrics','HTTP and JVM instrumentation plus compatible application instruments produce counters and histograms. Our outbox counter counts publishing <strong>attempts</strong>, not unique payments.')])+'''<h3>How does one trace stay connected?</h3><p>HTTP headers carry W3C <code>traceparent</code> context. Each service creates a child span under the same trace. Our outbox saves <code>traceparent</code>/<code>tracestate</code>, then restores them when the later publishing worker runs. That explicit restoration connects the payment to notification.</p><p><strong>Payment ID</strong> identifies the business transaction. <strong>Trace ID</strong> identifies one execution journey. <strong>Span ID</strong> identifies a step. <strong>Correlation ID</strong> is our operational request identifier. A retry can create a different trace for the same payment, so keep both business and trace IDs.</p><p>The agent does not trace every Java method. Baggage propagation is configured, but an application baggage feature has not been implemented or tested. Secrets and arbitrary baggage are not saved in the outbox.</p>''')
add('collector','4. Where does the evidence go?', '''<div class="flow"><div><b>Seven Java services</b><small>Generate logs, traces and metrics</small></div><span>↓ OTLP/HTTP</span><div><b>OTel Collector</b><small>Receive → memory checks → service identity → selected privacy filtering → batch → export</small></div><span>↓ three storage paths</span><div class="cards"><div><b>Loki</b><small>Stores logs</small></div><div><b>Tempo</b><small>Stores traces</small></div><div><b>Prometheus</b><small>Stores metrics</small></div></div><span>↓ queries</span><div><b>Grafana</b><small>Shows logs, waterfalls, charts and dashboards</small></div></div><p><strong>OTLP</strong> is the transport format. The Collector accepts our service payloads on port 4318, decodes them, and runs the configured pipeline for each signal. We push application metrics to the Collector; Prometheus then pulls its metrics endpoint. RabbitMQ metrics are pulled directly from the broker.</p><p>The Collector batches data, removes selected sensitive attributes and secret-like log patterns, and retries eligible export failures. Local trace/log export queues use disk so already-queued requests can recover after a crash. Buffers, retry windows and queue capacity are limited: telemetry can still be lost. Console output is not protected by Collector redaction.</p><p>Grafana queries stored evidence. It does not collect all the evidence itself. An “UP” health check only proves that a check succeeded, not that every payment or telemetry export succeeded.</p><p>Exact configuration: '''+source('observability/collector.yaml','Collector')+' · '+source('observability/prometheus.yaml','Prometheus')+' · '+source('observability/grafana/provisioning/datasources/datasources.yaml','Grafana connections')+'''.</p>''')
add('demo','5. Your first manual check: logs → waterfall → numbers', '''<p class="callout">The recorded test stack has been stopped. These localhost links work after you start the PoC on your own machine.</p><p>Install Git, Java 21, Maven, Docker/Compose v2, Python 3, curl, jq and sha256sum. Allow roughly 12 GB RAM. From a new checkout:</p>'''+code('git clone https://github.com/srinu7893/otel-payment-platform-poc.git\ncd otel-payment-platform-poc\ngit checkout feature/otel-observability-manual-e2e\nbash scripts/run-poc.sh start')+'''<ol><li>Open <a href="http://localhost:3000">Customer UI :3000</a>. Use isolated demo credentials <code>demo / demo123</code>. Submit a small fake payment and copy the actual payment ID.</li><li>Open <a href="http://localhost:3001/explore">Grafana Explore :3001</a>. Default demo login: <code>admin / otel-demo-admin</code>; use your override if changed. Select <strong>Loki</strong>, set Last 15 minutes, and run the payment-ID query below.</li><li>Expand the matching log. Read the event/outcome, timestamp, service and <code>trace_id</code>. Search that exact trace ID across services.</li><li>Select <strong>Tempo</strong> in Explore, use trace-ID lookup, and paste the ID. Open the waterfall. Expand the bank, JDBC, publishing and consumer spans. Widen the time range for delayed work.</li><li>Open the dashboards. Compare your specific trace with aggregate latency, errors, outcome events and queue health. Wait for export/scrape delay and refresh if new data has not arrived.</li></ol><h3>Raw logs: our closest equivalent to a Splunk event search</h3>'''+code('{service_name="payment-service"} |= "REPLACE_WITH_PAYMENT_ID"\n\n{service_name=~".+"} | trace_id="REPLACE_WITH_TRACE_ID"\n\n{service_name=~".+"}\n\n{service_name="payment-service"} |= "OUTBOX_PUBLISH_FAILED"')+'''<p>Run these in <strong>Loki</strong>. The third query returns stored logs from service-labelled streams in your chosen time window, subject to limits and retention. Add service filters, text filters or structured metadata filters. Loki uses <strong>LogQL</strong>, not Splunk SPL; not every console line, audit record or platform log is currently ingested.</p><h3>Find slow or failed bank traces</h3>'''+code('{ resource.service.name = "mock-bank-service" && duration > 2s }\n\n{ resource.service.name = "mock-bank-service" && status = error }')+'''<p>Run these in <strong>Tempo</strong> as TraceQL searches. A red span is an investigation clue; expand its status, exception event and attributes. Read the business outcome too. Some handled declines do not become HTTP 5xx.</p><p><strong>Reading the waterfall:</strong> horizontal length means duration; indentation means parent/child work. Find a long downstream call, slow database operation or large gap. Parallel spans overlap, so do not add every duration. Missing async work can mean delay, missing propagation, sampling or telemetry loss.</p>''')
add('numbers','6. Which dashboard and which numbers?',table(['Dashboard','Use it to answer'],[('<a href="http://localhost:3001/d/payment-poc">Payment operations</a>','Are services getting slower or returning errors? Compare request rate, p95 and JVM signals.'),('<a href="http://localhost:3001/d/payment-business">Business events</a>','Are payments completing, being declined or requiring reconciliation? What happened to notifications? Event counts are not guaranteed unique transactions.'),('<a href="http://localhost:3001/d/telemetry-pipeline">Telemetry pipeline</a>','Are publishing attempts failing? Are Collector queues/export failures or RabbitMQ backlog growing? Is our monitoring itself broken?'),('<a href="http://localhost:3001/d/payment-slo">Payment SLO</a>','Are technical HTTP availability and latency meeting the example target? Is the error budget being consumed quickly?')])+'''<p><strong>p95 latency</strong> means 95% of measured requests were at or below that duration. <strong>Error rate</strong> is failures divided by requests. <strong>Queue depth</strong> is waiting work. <strong>SLO</strong> is an agreed reliability target. This PoC uses an example 99.9% technical HTTP availability target; it is not an agreed business SLA.</p><h3>Useful Prometheus queries</h3>'''+code('sum by (service_name) (rate(http_server_request_duration_seconds_count[5m]))\n\nhistogram_quantile(0.95, sum by (le,service_name) (rate(http_server_request_duration_seconds_bucket[5m])))\n\nsum(increase(poc_outbox_publish_attempts_total{outcome="failure"}[5m]))\n\nrabbitmq_queue_messages_ready{queue="payments.notification"}\n\nALERTS{alertstate="firing"}')+'''<p>Run these in <a href="http://localhost:9090">Prometheus :9090</a>, or Grafana Explore with the Prometheus datasource. <code>rate</code> calculates per-second activity; <code>increase</code> estimates counter growth over the window. No data is not proof of zero failures. Sampled trace counts cannot replace unsampled request metrics.</p>''')
add('triage','7. When something breaks: check → act → verify',table(['Symptom','Check first','Safe action and recovery proof'],[
('Payment is slow','Operations p95 → payment-ID log → trace waterfall → bank and JDBC spans. Compare several requests.','Identify dependency or query before tuning. Restore the dependency or roll back a confirmed bad change using the approved release process. Verify p95 and business completion recover.'),('Bank timeout / 500 / exception','Bank error spans, gateway logs, payment outcome and reconciliation state. Read exception details without exposing secrets.','An unknown result may mean the bank already performed the operation. Reconcile first; do not create a fresh payment blindly. Verify one final business outcome and no duplicate bank operation.'),('Payment completed, no notification','Business log → outbox failure query → broker health → queue depth/consumer count → notification logs.','Restore broker/consumer availability. Let saved outbox work catch up. Verify delivery and draining backlog; do not repeat the payment.'),('Notification DLQ has messages','DLQ depth, bounded-retry logs, payload validation and consumer exception.','Fix the payload/consumer cause, then use an approved, deduplicated redrive. Verify one delivery. A bulk blind requeue can repeat the failure.'),('Grafana has no new logs/traces','Widen time range; check datasource, Collector health/internal metrics, queues, exporter errors and backend availability.','Repair the telemetry path. Verify a new known payment appears end to end. An empty dashboard may be monitoring failure rather than application recovery.'),('HTTP is healthy, business failures rise','Business events and durable payment state; risk/decline/reconciliation outcomes.','Separate expected declines from technical failures. Reconcile unknown results, investigate business rules or provider behavior. Confirm customer outcomes, not just HTTP 200.'),('Errors began after deployment','Compare start time, service version, previous baseline and affected traces.','Use compatible rollback if supported; HTTP rollback does not reverse database migrations, payments or worker effects. Check pending work and verify recovery.')])+'''<p>Detailed failure creation and reset steps are in the existing full guide and '''+source('scripts/e2e','scenario scripts')+'''. Run broker/Collector failure drills only against the disposable demo. Real failure windows and span timings vary.</p><h3>Alerting: seeing a warning is not the same as receiving a page</h3><p>Twelve local warning rules cover scrape failure, outbox failures, recorded span errors, Collector queue pressure/export failures, notification backlog/DLQ, payment HTTP budget burn, stale business snapshots, reconciliation and delivery-age problems. Rules now route through Alertmanager into a local incident inbox with owner, acknowledgement and resolution. Real on-call paging and escalation remain unconfigured. Open http://localhost:9094 for the inbox and http://localhost:9093 for Alertmanager; the support UI links to both locally.</p>''')
add('rca','8. MTTR and RCA: how this becomes useful to support', '''<p><strong>MTTR</strong> here means mean time to restore service. <strong>Triage</strong> means quickly identifying impact and the next useful investigation. <strong>RCA</strong> means explaining the confirmed cause and preventing recurrence.</p><ol><li><strong>Detect:</strong> record alert/customer-report time, affected feature and current version.</li><li><strong>Measure impact:</strong> affected window, errors, latency, backlog and confirmed customer outcomes.</li><li><strong>Locate:</strong> use the payment ID → log → trace. Identify the failing step and compare it with healthy requests.</li><li><strong>Restore:</strong> take the smallest approved action that addresses the evidence. Record action time and owner.</li><li><strong>Verify:</strong> check fresh transactions, latency/error trends, queue drainage and monitoring freshness.</li><li><strong>Explain:</strong> retain the timeline and evidence. Separate a suspected cause from a confirmed cause; assign prevention work.</li></ol><p class="callout">Illustrative incident: notifications stopped because RabbitMQ was unavailable. Payment rows still committed. Logs show publish failures; the publish-attempt counter rises; traces show the publishing step failing. Restore the broker, verify outbox catch-up and notification delivery, and investigate why the broker failed. OTel locates the symptom boundary; broker/network evidence confirms the underlying cause.</p>'''+code('Incident / owner:\nImpact and time window:\nPayment IDs and trace IDs (safe access only):\nQueries / dashboard links / source revision:\nObserved facts:\nSuspected cause → confirmed cause and proof:\nAction and time:\nRecovery checks:\nFollow-up owner and due date:')+'''<p>To demonstrate value, repeat the same failure drill with the old log-only process and this connected workflow. Measure time to detect, identify and restore; also count false alerts and unresolved incidents. We have not yet measured an MTTR improvement, so do not promise a percentage reduction.</p>''')
add('value','9. What does OTel add to an existing system?',table(['Existing capability','OTel adds','Value to our team'],[('Raw logs in Splunk or another store','Common service/context fields and trace correlation, if that backend supports the configured ingestion.','Follow an event into its cross-service execution instead of manually matching many log files.'),('CPU and basic service dashboards','Request latency/error metrics plus dependency traces and domain signals.','Distinguish infrastructure pressure, a slow bank call and a business decline.'),('Separate service debugging','HTTP/messaging propagation and explicit context at the durable outbox boundary.','See responsibility across teams and asynchronous work.'),('Vendor-specific agents/configuration','A standard instrumentation/Collector boundary with validated exporter choices.','Change or add a backend with less application instrumentation change; migration still requires testing.'),('Manual support investigation','Connected queries, runbooks and reproducible failure drills.','Reduce investigation steps and train support on repeatable evidence checks.')])+'''<p>We can keep an existing log system while adding OTel tracing/metrics or dual export. Splunk integration is not implemented in this PoC. There is no guarantee that every existing field, query or retention policy will transfer unchanged.</p>''')
add('enhancements','New: a realistic local support demonstration', '''<p><strong>Now implemented:</strong> database-backed payment/outbox/notification gauges, snapshot health/freshness, six new business panels, Alertmanager, a persistent incident inbox, and an on-demand synthetic payment journey.</p><ol><li>Run <code>python3 scripts/e2e/synthetic-journey.py</code> after starting the isolated demo. It checks login, bad credentials, payment completion, same-key replay and notification delivery.</li><li>Run <code>python3 scripts/e2e/support-acceptance.py</code> on disposable state. It compares metrics with PostgreSQL, stops the broker, creates a fake payment and waits for the delayed-outbox alert.</li><li>Open <a href="http://localhost:9094">Incident inbox</a>, acknowledge the incident and inspect its owner. The script acknowledges it during automated acceptance.</li><li>The script restores the broker in a finally block, verifies delivery catches up and checks that the same incident resolves. Acknowledgement alone never means the system recovered.</li></ol><p>Durable counts are gauges of current rows. Use <code>max by (status) (poc_payment_records)</code> and <code>max(poc_outbox_oldest_pending_seconds)</code>. Check <code>poc_business_snapshot_healthy</code> and timestamp freshness first. Counts from replicas sharing the same DB must not be summed.</p><p>Notification mean received-to-sent measures only consumer-record time, not complete payment-to-delivery time. Queries scan small PoC tables; production needs scale/timeout/privacy design. The local inbox is not deployed to GCP and does not send email, Slack or pager messages.</p><p>Implementation, queries and manual proof: '''+source('docs/SUPPORT_ENHANCEMENTS.md','support enhancement runbook')+'''.</p>''')
add('next','10. What should we build next? Highest value first', '''<p>This is the recommended backlog, <strong>not a list of newly implemented features</strong>. These remaining additions belong to application monitoring and operations as well as the OTel ecosystem. Local inbox routing, durable-state gauges and an on-demand journey have now been implemented; the table explains the remaining production work.</p>'''+table(['Priority / feature','Implementation for our services','Proof needed'],[
('1 · Production paging and ownership','Local Alertmanager/inbox now exist. Add a selected secure production notification channel, real owner and escalation policy.','Trigger a safe drill; prove one routed notification, acknowledgement/escalation and resolution.'),('1 · Durable business SLIs','Current payment/notification counts and oldest waiting ages now come from database snapshots. Next add windowed final-outcome SLIs and true payment-to-delivery latency. Avoid payment/customer IDs as metric labels.','Compare counts and timestamps with database truth; test delayed and duplicate events.'),('1 · Cloud acceptance','Provision the GCP dependencies and validate every signal, private IAM path, secret reference and UI query.','Run isolated fake payments and the manual cloud acceptance workflow; prove no public private-service access.'),('2 · Clearer domain spans and errors','Add bounded step names for risk/reconciliation/provider operations and structured exception events where missing.','A known failure exposes its step, safe error type and connected trace; no sensitive payload leakage.'),('2 · User-journey monitoring','An on-demand login/payment/replay/delivery check now exists. Next add safe scheduled journey checks and browser OTel/RUM with privacy-aware ingestion.','Detect a broken journey even when health endpoints are green. Browser tests alone are not RUM.'),('2 · DB/broker/cloud saturation','Add database connection-pool waits, slow-query evidence, worker/outbox age and provider infrastructure metrics.','A controlled bottleneck produces an actionable signal and a matching trace.'),('2 · Safer telemetry at scale','Design retention/cardinality/privacy budgets, durable gateways and trace-aware tail-sampling routing.','Test load, backend outage, queue exhaustion, loss and privacy across all log paths.'),('3 · Profiling','Evaluate Java continuous profiling/Pyroscope or another supported backend when CPU/memory diagnosis needs code-level detail.','A controlled CPU hotspot is identifiable with acceptable overhead; validate chosen versions.'),('3 · Fleet management / analytics','Evaluate OpAMP for many Collectors; use BigQuery for historical log/release analysis once GCP is live.','Authenticated config control/rollback, or verified bounded SQL results and cost limits.')])+'''<details><summary>Explore the wider OTel world — expand after reading the core guide</summary>'''+table(['Capability family','Meaning and our current position'],[
('APIs, SDKs and automatic instrumentation','Agent instrumentation plus selected manual outbox code exist. Add custom spans/events/instruments when library spans do not explain a business step.'),('Context, baggage and span links','Trace context works across HTTP/messaging/outbox. Baggage is configured only; safe allowlisted business baggage and late-work span links need implementation/testing.'),('Semantic conventions and resources','Common names identify service/environment/version. Validate consistent attributes and cloud mapping when upgrading. Bounded dimensions avoid exploding metric series.'),('Metrics instruments, histograms and exemplars','HTTP histograms/JVM/counters exist. Exemplars can link a metric observation to a sampled trace; destination configuration exists, but full click-through is not claimed.'),('Logs, events and exceptions','Business logs and selected redaction exist. Expand structured fields/error classification and privacy coverage. Full audit logging is a separate security requirement.'),('Collector receivers/processors/exporters/connectors','OTLP, memory/resource/privacy/batch and backend exporters are used. File logs, host/DB receivers, routing/filtering/transforms or connector metrics need concrete requirements and version-specific tests.'),('Sampling and telemetry self-monitoring','Error/slow/normal tail-sampling experiment and queue/export metrics are tested locally. Cloud sidecar queues are ephemeral; scale and late-span handling remain work.'),('Browser/mobile/serverless/Kubernetes','Java backend scope is implemented; browser/mobile telemetry and Kubernetes/host collection are not. Cloud Run manifests are prepared, not deployed.'),('Profiles, eBPF and remote management','Profiling, eBPF and OpAMP are evaluated options, not installed features. The OTel profiles protocol is still marked development in the checked official status page.'),('SLOs, paging, RCA, chaos and analytics','These use telemetry but are not automatic OTel features. Technical SLO rules exist; real paging, measured MTTR, production chaos/HA/DR and historical analytics need separate work.')])+'''<p>There is no useful “all features complete” checkbox across every language, backend and platform. Select a feature because it answers an operational question, then demonstrate its integration and failure behavior.</p></details>''')
add('cloud','11. How GCP and BigQuery fit later', '''<p>The prepared design deploys <strong>seven Java services separately, plus one frontend</strong>. Each Java service has a Collector sidecar. PostgreSQL and RabbitMQ need durable services outside these application containers. Native exports target Cloud Logging, Cloud Trace and Managed Prometheus; optional Grafana Cloud fan-out is prepared.</p><p><strong>BigQuery</strong> is useful for longer-term SQL analysis and joins: outcomes over time, incidents by release, repeated failure patterns. The prepared approach links a Cloud Logging analytics bucket to BigQuery. It does not replace the span-waterfall UI, operational alerts or the payment database.</p><p>Live GCP/Grafana Cloud/BigQuery integration has not run. Configuration validation is not cloud acceptance. Prerequisites and SQL: '''+source('docs/CLOUD_RUN_PLAN.md','cloud runbook')+' · '+source('deploy/bigquery/queries.sql','BigQuery examples')+'''.</p>''')
add('proof','12. What is tested, and how to explain it to your manager', '''<p>The current evidence reference is <a href="https://github.com/srinu7893/otel-payment-platform-poc/actions/runs/RUN_PLACEHOLDER">manual E2E run</a>, source <code>REV_PLACEHOLDER</code>. Backend report count: TEST_COUNT_PLACEHOLDER. The full guide records each pipeline outcome, 15 base telemetry/security/recovery scenarios, browser checks, tail sampling, selected redaction and SLO tests. SUPPORT_STATUS_PLACEHOLDER. Cloud assets are validated without live cloud credentials; that is not a cloud deployment.</p><p>For a fresh automated demonstration, use the separate manual workflow. Before merge, the same-repository PR can be run by manually applying the <code>run-otel-e2e</code> label; the Run workflow button is available once the manual workflow is on the default branch. Full E2E is not triggered on every ordinary build. Local <code>bash scripts/run-poc.sh test</code> runs a subset against fresh disposable state; it does not reproduce every browser/cloud/sampling check.</p><div class="callout"><b>A simple manager explanation</b><p>“Our payment crosses several services and later sends a queued notification. OpenTelemetry connects that journey. Logs explain the outcome, traces identify the slow or failed step, and metrics show the wider impact. We demonstrated successful flows, bank errors, broker outages and telemetry recovery. Support can use the same evidence to investigate and verify recovery. Cloud deployment and production alert delivery are the next gates.”</p></div><p>This simpler companion is dated 5 October 2026. It explains the recorded PoC; it is not an automatically updating health report. The detailed guide remains the configuration/evidence reference. Update this companion when service flows, queries or feature status change.</p>''')
add('sources','Official references and source links', '''<p>Project: <a href="https://github.com/srinu7893/otel-payment-platform-poc/pull/3">PR #3</a>. Repository links follow the implementation branch; the evidence section identifies the tested source revision. Recommendations are our application-specific design judgment.</p><ul><li><a href="https://opentelemetry.io/docs/concepts/signals/">OTel signals</a>: logs, metrics, traces and context concepts.</li><li><a href="https://opentelemetry.io/docs/zero-code/java/agent/">Java agent</a>: automatic Java instrumentation.</li><li><a href="https://opentelemetry.io/docs/collector/configuration/">Collector configuration</a>: receivers, processors, exporters and pipelines.</li><li><a href="https://opentelemetry.io/docs/concepts/sampling/">Sampling</a>: selecting traces and tradeoffs.</li><li><a href="https://opentelemetry.io/docs/specs/status/">Specification status</a>: signal maturity and profiles development.</li><li><a href="https://opentelemetry.io/docs/languages/js/getting-started/browser/">Browser instrumentation</a> and <a href="https://opentelemetry.io/docs/collector/management/">Collector management</a>: future integration references.</li><li><a href="https://docs.cloud.google.com/logging/docs/analyze/query-linked-dataset">Cloud Logging linked BigQuery dataset</a>: planned analytics path.</li></ul>''')
css='''*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#17283a;font:17px/1.65 system-ui,sans-serif}header{background:#12354c;color:white;padding:48px max(24px,calc((100vw - 1000px)/2))}header p{color:#d7e9f5;max-width:820px}h1{font-size:38px;line-height:1.2;margin:10px 0}h2{font-size:27px;line-height:1.3;margin:0 0 18px}h3{font-size:21px}main{max-width:1060px;margin:auto;padding:24px}nav,section{background:white;border:1px solid #dbe4eb;border-radius:14px;padding:30px;margin-bottom:24px}nav a{display:block;margin:6px 0}a{color:#075e91;text-underline-offset:3px}p{margin:12px 0}li{margin:9px 0}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.cards>div{background:#eef5fa;border:1px solid #d5e5ef;border-radius:10px;padding:16px}.cards p{font-size:16px}.callout{background:#edf8f3;border-left:5px solid #23835d;padding:18px;margin:20px 0}.scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:16px}th,td{text-align:left;vertical-align:top;border-bottom:1px solid #dbe4eb;padding:13px}th{background:#edf3f7}td:first-child{font-weight:600;min-width:160px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#102a3c;color:#e0f2ff;padding:20px;border-radius:10px;font-size:14px;line-height:1.7}p code,li code{background:#edf2f5;border-radius:4px;padding:2px 5px;font-size:14px;overflow-wrap:anywhere}.flow{text-align:center;margin:24px 0}.flow>div{padding:14px;background:#edf4f8;border-radius:10px}.flow span{display:block;padding:8px;color:#557085}.flow small{display:block}details{border:1px solid #cbd9e3;padding:20px;border-radius:10px;margin-top:22px}summary{font-weight:700;cursor:pointer}footer{padding:20px;text-align:center;font-size:14px;color:#597183}@media(max-width:700px){.cards{grid-template-columns:1fr}main{padding:12px}section,nav{padding:20px}h1{font-size:30px}table{font-size:14px}}@media print{body{background:white;font-size:12px}nav{display:none}header{padding:20px;background:white;color:#12354c}header p{color:#17283a}main{padding:0}section{border:0;padding:16px;break-inside:auto}h2,h3{break-after:avoid}tr,.callout{break-inside:avoid}pre{color:#17283a;background:#edf2f5}a{color:#17283a}details{display:block}}'''
